import{z as n,x as p,o as E,c as B,q as l,j as i,D as e,d as t,s as o,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"PFAS 与光刻胶管制","description":"","frontmatter":{"title":"PFAS 与光刻胶管制","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pfas-resist-regulation.md","filePath":"litho/pfas-resist-regulation.md","lastUpdated":1791063341000}'),d={name:"litho/pfas-resist-regulation.md"};function P(h,a,m,S,f,u){const s=p("Mermaid");return E(),B("div",null,[a[2]||(a[2]=l('<h1 id="pfas-与光刻胶管制" tabindex="-1">PFAS 与光刻胶管制 <a class="header-anchor" href="#pfas-与光刻胶管制" aria-label="Permalink to &quot;PFAS 与光刻胶管制&quot;">​</a></h1><div class="epigraph"><p>光酸发生剂与表面活性剂常含氟烷基；PFAS 管制若一刀切，先进胶配方会先于光学碰到法规墙。</p><footer>—— 对照半导体光刻中 PFAS 用途与 2020s 监管讨论的公开产业/SPIE 叙述</footer></div><p><a href="/litho/supply-chain-single-source">上一课</a>谈工具集中。缺口是材料许可。本课钉 PFAS 与光刻胶管制。代工如何在法规与工具约束下选节点路径，留给<a href="/litho/foundry-roadmap-compare">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>化学放大胶的 PAG、猝灭剂、表面活性剂、底部抗反射，不少属于广义 PFAS 讨论范围。监管（欧盟等）若限制制造与进口，供应链会像工具一样窄。替代配方必须重新做窗口、随机、缺陷、与 OPC 版本——学习曲线时钟重启。</p><p><span class="marginnote">PFAS（全氟/多氟烷基物质）是一大类碳链上的氢被氟替换的化合物：碳氟键极其稳定，既抗分解又低表面能。光刻恰好看中这两点——PAG 的酸强度、胶的透明度、表面活性剂的铺展都靠氟化学；但「极难分解」也正是环保管制盯上它的原因。</span></p><p>缺口是<strong>法规进 PDK</strong>，不是再讲酸扩散。把胶当无限可购的化学品，规划会漏项。</p><h3 id="不要把化学点名写成禁令清单" tabindex="-1">不要把化学点名写成禁令清单 <a class="header-anchor" href="#不要把化学点名写成禁令清单" aria-label="Permalink to &quot;不要把化学点名写成禁令清单&quot;">​</a></h3><p>具体物质与豁免随法域与年份变。本课钉机制：先进节点胶高度依赖含氟功能，替代有周期。不把某公司退出当全球停产的完成时。</p><p><span class="marginnote">湿法与管线里的表面活性剂同样受关注，不只是涂在晶圆上的那一微米。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>跟踪：法规范围、豁免、时间表。工程：替代 PAG 的资格矩阵（E0、LER、随机、金属污染）。版本：胶换即模型换。与出口管制并列进风险登记，对象不同。</p>',12)),(E(),i(A,null,{default:e(()=>[o(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%B3%95%E8%A7%84%E9%99%90%E5%88%B6%E6%9F%90%E5%90%AB%E6%B0%9F%E7%BB%84%E5%88%86%22%5D%20--%3E%20SUB%5B%22%E5%80%99%E9%80%89%E6%9B%BF%E4%BB%A3%E9%85%8D%E6%96%B9%22%5D%0A%20%20SUB%20--%3E%20E0%5B%22%E7%AA%97%E5%8F%A3%E4%B8%8E%E7%81%B5%E6%95%8F%E5%BA%A6%20E0%22%5D%0A%20%20SUB%20--%3E%20LER%5B%22LER%20%E4%B8%8E%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20SUB%20--%3E%20DEF%5B%22%E7%BC%BA%E9%99%B7%E4%B8%8E%E9%87%91%E5%B1%9E%E6%B1%A1%E6%9F%93%22%5D%0A%20%20SUB%20--%3E%20OPC%5B%22OPC%20%E6%A8%A1%E5%9E%8B%E9%87%8D%E6%A0%87%E5%AE%9A%22%5D%0A%20%20E0%20--%3E%20GATE%7B%22%E5%85%A8%E9%83%A8%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20LER%20--%3E%20GATE%0A%20%20DEF%20--%3E%20GATE%0A%20%20OPC%20--%3E%20GATE%0A%20%20GATE%20--%3E%7C%22%E6%98%AF%22%7C%20VOL%5B%22%E9%87%8F%E4%BA%A7%E7%88%AC%E5%9D%A1%22%5D%0A%20%20GATE%20--%3E%7C%22%E5%90%A6%22%7C%20SUB%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"含氟基团提供酸强度、透明度、表面能，是配方自由度。去掉它们不是改浓度，是改一类化学。资格周期以年计，与节点爬坡重叠则直接进良率学习。",-1)),(E(),i(A,null,{default:e(()=>[o(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22PFAS%20%E6%B3%95%E8%A7%84%22%5D%20--%3E%20SUP%5B%22%E8%83%B6%20%2F%20%E8%A1%A8%E9%9D%A2%E6%B4%BB%E6%80%A7%E5%89%82%E4%BE%9B%E7%BB%99%22%5D%0A%20%20SUP%20--%3E%20QUAL%5B%22%E9%87%8D%E6%96%B0%E8%B5%84%E6%A0%BC%20%2B%20OPC%22%5D%0A%20%20QUAL%20--%3E%20CLK%5B%22%E5%AD%A6%E4%B9%A0%E6%97%B6%E9%92%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">为什么换胶等于换模型：显影阈值、酸扩散长度、LER 统计全部随配方变，之前调好的 OPC 模型与剂量网格建立在这些数字上。换一种 PAG 不是「换个供应商再验一下」，而是整套计算光刻参数重标，学习曲线从零再走。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供法律意见。不发明未公布的禁令日期。不把所有氟化学当同一监管对象。</p><p><span class="marginnote">初学者容易以为「管制 PFAS 就是禁一种物质」。实际上 PFAS 是数千种分子的家族，各法域、各年份划定的范围与豁免不同：有的豁免半导体光刻胶，有的限期申报。把新闻标题直接当禁令日期写进规划，是最贵的错误。</span></p><p>后课默认：材料许可是约束；下一课代工路线在工具、材料、节点名下如何分叉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先进胶与湿法含 PFAS 讨论对象；管制会重启资格与 OPC。</li><li>替代不是调浓度，是换化学自由度。</li><li>与工具集中并列，进风险登记。</li><li>出处：光刻 PFAS 用途与监管的公开产业/SPIE 讨论。</li></ul>',7))])}const D=n(d,[["render",P]]);export{F as __pageData,D as default};
